def arraySign(nums):
    negative_count = 0

    for num in nums:
        if num == 0:
            return 0
        elif num < 0:
            negative_count += 1

    # If even number of negatives, product is positive
    # If odd number of negatives, product is negative
    return 1 if negative_count % 2 == 0 else -1
```

